package org.xingmu.tv;
import android.app.*;import android.os.*;import android.content.*;import android.widget.*;import android.view.*;import java.util.*;import java.util.concurrent.*;import androidx.media3.exoplayer.offline.*;
@androidx.annotation.OptIn(markerClass=androidx.media3.common.util.UnstableApi.class)
public final class DownloadsActivity extends Activity {
 private final Handler handler=new Handler();private final ExecutorService worker=Executors.newSingleThreadExecutor();private final List<Download> entries=new ArrayList<>();private ArrayAdapter<String> adapter;private TextView status;private boolean active;
 private final Runnable tick=()->refresh();
 @Override public void onCreate(Bundle state){super.onCreate(state);LinearLayout root=TvUi.root(this);LinearLayout header=TvUi.row(this);header.addView(TvUi.title(this,"下载中心",26),new LinearLayout.LayoutParams(0,-2,1));Button back=TvUi.button(this,"返回");header.addView(back);back.setOnClickListener(v->finish());root.addView(header);TvUi.gap(this,root,12);root.addView(TvUi.text(this,"视频统一保存于应用专用目录，下载完成后可离线观看。点击已完成影片播放，长按删除或查看详情。卸载应用会删除这些视频。",14,TvUi.MUTED));LinearLayout controls=TvUi.row(this);Button pause=TvUi.button(this,"全部暂停"),resume=TvUi.button(this,"继续下载");controls.addView(pause,new LinearLayout.LayoutParams(0,-2,1));controls.addView(resume,new LinearLayout.LayoutParams(0,-2,1));root.addView(controls);pause.setOnClickListener(v->act(()->DownloadService.sendPauseDownloads(this,OfflineDownloadService.class,true)));resume.setOnClickListener(v->act(()->DownloadService.sendResumeDownloads(this,OfflineDownloadService.class,true)));status=TvUi.text(this,"正在读取下载任务…",14,TvUi.MUTED);root.addView(status);ListView list=new ListView(this);adapter=new ArrayAdapter<String>(this,android.R.layout.simple_list_item_1,new ArrayList<>()){public View getView(int n,View reused,ViewGroup parent){TextView t=TvUi.text(DownloadsActivity.this,getItem(n),16,TvUi.INK);t.setPadding(16,16,16,16);t.setBackground(TvUi.channelFocus());return t;}};list.setAdapter(adapter);root.addView(list,new LinearLayout.LayoutParams(-1,0,1));list.setOnItemClickListener((p,v,n,id)->open(entries.get(n)));list.setOnItemLongClickListener((p,v,n,id)->{options(entries.get(n));return true;});}
 private void act(Runnable action){try{action.run();handler.removeCallbacks(tick);handler.postDelayed(tick,400);}catch(RuntimeException e){TvUi.toast(this,"操作失败："+e.getMessage());}}
 private void open(Download download){if(download.state==Download.STATE_COMPLETED&&OfflineStore.usable(download))startActivity(new Intent(this,PlayerActivity.class).putExtra("download_id",download.request.id));else TvUi.toast(this,download.state==Download.STATE_COMPLETED?"此任务内容未验证，请长按后重新下载":"下载完成后可播放，长按可管理任务");}
 private void remove(Download download){new AlertDialog.Builder(this).setTitle("删除视频与下载任务？").setNegativeButton("取消",null).setPositiveButton("删除",(x,y)->act(()->DownloadService.sendRemoveDownload(this,OfflineDownloadService.class,download.request.id,true))).show();}
 private void details(Download download){CatalogItem item=OfflineStore.item(download);String size=String.format(Locale.ROOT,"%.2f MB (%d 字节)",download.getBytesDownloaded()/1048576d,download.getBytesDownloaded());String total=download.contentLength<0?"未提供":String.format(Locale.ROOT,"%.2f MB",download.contentLength/1048576d);String date=java.text.DateFormat.getDateTimeInstance().format(new java.util.Date(download.startTimeMs));new AlertDialog.Builder(this).setTitle("影片详细信息").setMessage("名称："+item.title+"\n分类："+item.category+"\n来源："+item.source+"\n状态："+label(download)+"\n已下载："+size+"\n总大小："+total+"\n格式："+(download.request.mimeType==null?"普通视频文件":download.request.mimeType)+"\n添加时间："+date+"\n存储位置：应用专用 offline-media 目录").setPositiveButton("关闭",null).show();}
 private void options(Download download){boolean invalid=download.state==Download.STATE_COMPLETED&&!OfflineStore.usable(download),done=download.state==Download.STATE_COMPLETED&&!invalid;String[] actions=done?new String[]{"删除","详细信息"}:new String[]{download.state==Download.STATE_FAILED||invalid?"重新下载":download.stopReason==0?"暂停此任务":"继续此任务","删除","详细信息"};new AlertDialog.Builder(this).setTitle(OfflineStore.item(download).title).setItems(actions,(d,n)->{if(done){if(n==0)remove(download);else details(download);}else if(n==2)details(download);else if(n==1)remove(download);else if(download.state==Download.STATE_FAILED||invalid)act(()->OfflineStore.retry(this,download));else act(()->{DownloadService.sendSetStopReason(this,OfflineDownloadService.class,download.request.id,download.stopReason==0?1:0,true);DownloadService.sendResumeDownloads(this,OfflineDownloadService.class,true);});}).show();}
 private void refresh(){if(!active)return;worker.execute(()->{try{List<Download> data=OfflineStore.list(this);runOnUiThread(()->{if(!active)return;entries.clear();entries.addAll(data);adapter.clear();int done=0;long bytes=0;for(Download d:data){if(d.state==Download.STATE_COMPLETED&&OfflineStore.usable(d))done++;bytes+=d.getBytesDownloaded();adapter.add(OfflineStore.item(d).title+"\n"+label(d)+" · "+String.format(Locale.ROOT,"%.1f MB",d.getBytesDownloaded()/1048576d));}adapter.notifyDataSetChanged();status.setText(data.isEmpty()?"暂无下载。可在影片选集页或播放菜单中添加。":data.size()+" 个任务 · "+done+" 个已完成 · "+String.format(Locale.ROOT,"%.1f MB",bytes/1048576d));handler.removeCallbacks(tick);handler.postDelayed(tick,1500);});}catch(Exception e){runOnUiThread(()->{if(active){status.setText("读取下载失败："+e.getMessage());handler.postDelayed(tick,3000);}});}});}
 private String label(Download d){switch(d.state){case Download.STATE_COMPLETED:return OfflineStore.usable(d)?"已完成 · 可离线观看":"内容未验证或为空 · 长按重新下载";case Download.STATE_FAILED:return "下载失败 · 长按重试";case Download.STATE_STOPPED:return "已暂停";case Download.STATE_REMOVING:return "正在删除";case Download.STATE_DOWNLOADING:return d.getPercentDownloaded()<0?"正在下载":String.format(Locale.ROOT,"正在下载 %.0f%%",d.getPercentDownloaded());default:return OfflineStore.manager(this).getDownloadsPaused()?"已暂停":"等待网络或空闲下载位";}}
 @Override protected void onStart(){super.onStart();active=true;refresh();}
 @Override protected void onStop(){active=false;handler.removeCallbacks(tick);super.onStop();}
 @Override protected void onDestroy(){worker.shutdownNow();super.onDestroy();}
}
